/* ---- js/dorskilt.js ---- */
// Dørskilt i akryl (146 × 96 mm): topptekst, motiv i midten og navn nederst.
// Motivene er tegnet som vektorer (mm) i samme stil som skiltene: hvite, enkle
// silhuetter. Gir forhåndsvisning (sort akryl, hvit gravering, stålholdere) og
// SVG av hele skiltet til LightBurn. Bygger på window.TextEngrave.
(function () {
  'use strict';
  const TE = window.TextEngrave;

  const SIGN = {
    label: 'Dørskilt i akryl',
    w: 146, h: 96, r: 3,
    holes: [[8, 8], [138, 8], [8, 88], [138, 88]], holeR: 2.5, capR: 6.5,
    // Feltene er målt fra originaldesignet (fjellskiltet, 10,52 px/mm):
    // «Velkommen» 113 × 20 mm, «TIL VÅRT HJEM» store bokstaver 9,6 mm,
    // motiv 46–72 mm fra toppen, navn to linjer à 6,65 mm med 3,1 mm mellomrom.
    fields: {
      top1:  { cx: 73.05, cy: 14.95, w: 114, h: 20.9 },
      top2:  { cx: 73,    cy: 35.55, w: 104, h: 10.2 },
      motif: { cx: 73,    cy: 58.85, w: 104, h: 25.7 },
      names: { cx: 73,    cy: 83.08, w: 112, h: 17.05 },
    },
  };

  // ---------- Små tegnehjelpere (mm, y nedover). Positive former med klokka,
  // hull mot klokka, så de fungerer med vanlig «nonzero»-fyll i SVG og LightBurn.
  const f = (v) => (+v.toFixed(3)).toString();
  function area(pts) { let a = 0; for (let i = 0; i < pts.length; i++) { const [x1, y1] = pts[i], [x2, y2] = pts[(i + 1) % pts.length]; a += x1 * y2 - x2 * y1; } return a / 2; }
  function poly(pts, hole = false) {
    const cw = area(pts) > 0;              // med y nedover betyr positivt areal «med klokka»
    if (cw === hole) pts = pts.slice().reverse();
    return 'M' + pts.map(([x, y]) => f(x) + ' ' + f(y)).join(' L') + ' Z';
  }
  function circle(cx, cy, r, hole = false, n = 20) {
    const pts = []; for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2; pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]); }
    return poly(pts, hole);
  }
  // Kurve samplet til polygon (enklere å orientere riktig)
  function quad(p0, p1, p2, n = 10) { const out = []; for (let i = 1; i <= n; i++) { const t = i / n, u = 1 - t; out.push([u * u * p0[0] + 2 * u * t * p1[0] + t * t * p2[0], u * u * p0[1] + 2 * u * t * p1[1] + t * t * p2[1]]); } return out; }
  // Avsmalnende strek (som en penselstrek): tykkest på midten
  function taper(x1, x2, y, t) { return poly([[x1, y], [(x1 + x2) / 2, y - t / 2], [x2, y], [(x1 + x2) / 2, y + t / 2]]); }
  function star(cx, cy, r) { return poly([[cx, cy - r], [cx + r * 0.22, cy - r * 0.22], [cx + r, cy], [cx + r * 0.22, cy + r * 0.22], [cx, cy + r], [cx - r * 0.22, cy + r * 0.22], [cx - r, cy], [cx - r * 0.22, cy - r * 0.22]]); }
  function pine(x, base, h) {
    const w = h * 0.5, parts = [];
    parts.push(poly([[x - h * 0.035, base], [x + h * 0.035, base], [x + h * 0.035, base - h * 0.14], [x - h * 0.035, base - h * 0.14]]));
    const tiers = 4;
    for (let i = 0; i < tiers; i++) {
      const tb = base - h * 0.1 - i * h * 0.2, tw = w * (1 - i * 0.2), tt = tb - h * 0.34;
      parts.push(poly([[x - tw / 2, tb], [x + tw / 2, tb], [x, Math.max(tt, base - h)]]));
    }
    return parts.join(' ');
  }
  function bird(x, y, s) {
    const l = [[x - 2.4 * s, y - 0.6 * s], ...quad([x - 2.4 * s, y - 0.6 * s], [x - 1.2 * s, y - 1.2 * s], [x, y], 6), ...quad([x, y], [x + 1.3 * s, y - 1.5 * s], [x + 2.8 * s, y - 1.1 * s], 6),
      ...quad([x + 2.8 * s, y - 1.1 * s], [x + 1.3 * s, y - 0.9 * s], [x, y + 0.45 * s], 6), ...quad([x, y + 0.45 * s], [x - 1.2 * s, y - 0.6 * s], [x - 2.4 * s, y - 0.6 * s], 6)];
    return poly(l);
  }
  function cubic(p0, p1, p2, p3, n = 12) { const o = []; for (let i = 1; i <= n; i++) { const t = i / n, u = 1 - t; o.push([u*u*u*p0[0] + 3*u*u*t*p1[0] + 3*u*t*t*p2[0] + t*t*t*p3[0], u*u*u*p0[1] + 3*u*u*t*p1[1] + 3*u*t*t*p2[1] + t*t*t*p3[1]]); } return o; }
  function heart(cx, cy, w) {
    const h = w * 0.9, x = cx - w / 2, t = cy - h / 2, P = (fx, fy) => [x + fx * w, t + fy * h];
    const pts = [P(0.5, 0.28), ...cubic(P(0.5, 0.28), P(0.5, 0), P(0, 0), P(0, 0.3)), ...cubic(P(0, 0.3), P(0, 0.62), P(0.38, 0.8), P(0.5, 1)),
      ...cubic(P(0.5, 1), P(0.62, 0.8), P(1, 0.62), P(1, 0.3)), ...cubic(P(1, 0.3), P(1, 0), P(0.5, 0), P(0.5, 0.28))];
    return poly(pts);
  }
  // Halvmåne: del av sirkel A som ligger utenfor sirkel B
  function crescent(cx, cy, r, ox, oy, r2) {
    const pts = [], n = 60, inB = (x, y) => (x - ox) ** 2 + (y - oy) ** 2 < r2 * r2;
    for (let i = 0; i < n; i++) { const a = (i / n) * Math.PI * 2, x = cx + r * Math.cos(a), y = cy + r * Math.sin(a); if (!inB(x, y)) pts.push([x, y, a]); }
    // start ved et punkt rett etter et hopp, så buen blir sammenhengende
    let k = 0; for (let i = 1; i < pts.length; i++) if (pts[i][2] - pts[i - 1][2] > (Math.PI * 2) / n * 1.5) k = i;
    const outer = pts.slice(k).concat(pts.slice(0, k)).map(([x, y]) => [x, y]);
    const [sx, sy] = outer[0], [ex, ey] = outer[outer.length - 1];
    const a0 = Math.atan2(ey - oy, ex - ox), a1 = Math.atan2(sy - oy, sx - ox);
    let da = a1 - a0; while (da > 0) da -= Math.PI * 2;          // indre bue (sirkel B) tilbake
    const inner = []; for (let i = 1; i < 30; i++) { const a = a0 + da * (i / 30); inner.push([ox + r2 * Math.cos(a), oy + r2 * Math.sin(a)]); }
    return poly(outer.concat(inner));
  }
  const dots = (x1, x2, y, r = 0.32, step = 1.7) => { const o = []; for (let x = x1; x <= x2 + 0.01; x += step) o.push(circle(x, y, r, false, 10)); return o.join(' '); };
  function waves(x1, x2, y, amp, len, t) {
    const top = [], bot = [];
    for (let x = x1; x <= x2 + 0.01; x += 0.5) {
      const k = (x - x1) / (x2 - x1), w = t * Math.sin(Math.PI * k);          // tynnere i endene
      const yy = y + amp * Math.sin((x - x1) / len * Math.PI * 2);
      top.push([x, yy - w / 2]); bot.push([x, yy + w / 2]);
    }
    return poly(top.concat(bot.reverse()));
  }

  // ---------- Motivene (boks 104 × 20 mm, origo øverst til venstre) ----------
  const traced = (key, label) => ({ label, abs: true, rule: 'evenodd', build: () => (window.DoorSignTraced && window.DoorSignTraced[key]) || '' });
  const MOTIFS = {
    // Fjell: sporet fra originaldesignet (tools/trace-motif.py), med egen plassering i mm.
    fjell: { label: 'Fjell', abs: true, rule: 'evenodd', build: () => (window.DoorSignTraced && window.DoorSignTraced.fjell) || MOTIFS.fjellTegnet.build() },
    fjellTegnet: { label: 'Fjell (tegnet)', hidden: true, build() {
      const g = 17.2, p = [];
      // fjellet med en mørk rygglinje (hull)
      const m = [[10, g], ...quad([10, g], [22, 13], [28, 9], 8), [33, 4.2], [35, 3.4], ...quad([35, 3.4], [40, 7.5], [47, 11], 8), ...quad([47, 11], [54, 14.5], [62, g], 8)];
      p.push(poly(m));
      p.push(poly([[34.6, 4.6], [32.5, 7.6], [30.2, 10.6], [27.6, 13.3], [25.2, 15.4], [26.0, 15.5], [28.4, 13.5], [31.0, 10.9], [33.3, 8.0], [35.1, 5.2]], true));
      p.push(taper(4, 100, g + 0.15, 0.7));
      p.push(pine(70, g, 15.5));
      p.push(poly([[75.5, g], [76.2, 15.8], [76.6, g], [77.2, 15.4], [77.7, g]]));     // gresstust
      p.push(bird(88, 6.5, 1.15));
      p.push(star(15, 6, 1.1), star(19.5, 9.5, 0.6), star(95, 11.5, 0.9));
      p.push(dots(6, 98, 19.6));
      return p.join(' ');
    } },
    // Strektegnede motiver sporet fra motivarket (tools/trace-motifs.py), allerede plassert i motivfeltet.
    hus: traced('hus', 'Hus'),
    blomster: traced('blomster', 'Blomster'),
    hjerter: traced('hjerter', 'Hjerter'),
    hjort: traced('hjort', 'Hjort'),
    pote: traced('pote', 'Pote'),
    fisk: traced('fisk', 'Fisk'),
    eng: traced('eng', 'Eng'),
    // Eldre tegnede motiver: skjult i editoren, men beholdt så tidligere bestillinger kan eksporteres.
    hjerte: { label: 'Hjerte', hidden: true, build() {
      return [taper(14, 46, 10.6, 0.9), taper(58, 90, 10.6, 0.9), heart(52, 10.4, 6.6)].join(' ');
    } },
    hytte: { label: 'Hytte', hidden: true, build() {
      const g = 17.2, p = [];
      p.push(taper(8, 96, g + 0.15, 0.7));
      // hytta: vegg med dør og vinduer som hull, tak med utstikk og pipe
      p.push(poly([[43, g], [61, g], [61, 9.6], [43, 9.6]]));
      p.push(poly([[50.7, g - 0.01], [53.3, g - 0.01], [53.3, 12.4], [50.7, 12.4]], true));
      p.push(poly([[45.2, 14.6], [48.6, 14.6], [48.6, 11.6], [45.2, 11.6]], true));
      p.push(poly([[55.4, 14.6], [58.8, 14.6], [58.8, 11.6], [55.4, 11.6]], true));
      p.push(poly([[40.5, 10.2], [63.5, 10.2], [52, 3.2]]));
      p.push(poly([[56.5, 6.8], [58.4, 6.8], [58.4, 3.6], [56.5, 3.6]]));
      p.push(pine(33, g, 12.5), pine(27, g, 9), pine(71, g, 14.5), pine(78, g, 10));
      p.push(circle(63.5, 2.3, 0.55), circle(64.6, 1.1, 0.4));                      // røyk
      p.push(star(16, 6, 1.0), star(88, 5, 1.1), star(93, 9.5, 0.6));
      return p.join(' ');
    } },
    skog: { label: 'Skog', hidden: true, build() {
      const g = 17.2, p = [taper(8, 96, g + 0.15, 0.7)];
      for (const [x, h] of [[24, 9], [31, 13], [38, 10.5], [46, 15.5], [54, 12], [61, 14], [69, 10], [76, 12.5], [83, 8.5]]) p.push(pine(x, g, h));
      // halvmåne (sirkel minus forskjøvet sirkel) og stjerner
      p.push(crescent(92, 4.6, 2.4, 93.2, 3.8, 2.0));
      p.push(star(14, 5, 1.0), star(18.5, 9, 0.6), star(86, 9, 0.6));
      return p.join(' ');
    } },
    fyr: { label: 'Fyrlykt', hidden: true, build() {
      const p = [];
      // tårn (trapes) med to mørke striper, lanterne, tak og lysstråler
      p.push(poly([[48.2, 16.4], [55.8, 16.4], [54.4, 6.2], [49.6, 6.2]]));
      p.push(poly([[48.65, 13.0], [55.35, 13.0], [55.15, 11.6], [48.85, 11.6]], true));
      p.push(poly([[49.1, 9.6], [54.9, 9.6], [54.75, 8.4], [49.25, 8.4]], true));
      p.push(poly([[49.0, 5.9], [55.0, 5.9], [55.0, 5.2], [49.0, 5.2]]));
      p.push(poly([[49.8, 5.0], [54.2, 5.0], [54.2, 3.3], [49.8, 3.3]]));
      p.push(poly([[50.6, 4.6], [53.4, 4.6], [53.4, 3.7], [50.6, 3.7]], true));
      p.push(poly([[49.2, 3.2], [54.8, 3.2], [52, 1.2]]));
      p.push(poly([[55.6, 3.6], [72, 1.2], [72, 6.2]]), poly([[48.4, 3.6], [32, 1.2], [32, 6.2]]));
      p.push(poly([[45, 16.9], [59, 16.9], [57.5, 15.9], [46.5, 15.9]]));               // klippe
      p.push(waves(10, 94, 17.7, 0.45, 6, 0.8));
      p.push(bird(80, 7, 0.9), bird(86.5, 10, 0.7));
      return p.join(' ');
    } },
    ingen: { label: 'Uten motiv', build: () => '' },
  };
  const motifCache = {};
  const motifD = (key) => (motifCache[key] = motifCache[key] || (MOTIFS[key] || MOTIFS.ingen).build());

  // ---------- Oppsett ----------
  // recipe: { top1: {text, font}, top2, top2Font, motif, names: [l1, l2] }
  // Skrivestiler graveres som skrevet, de andre skriftene med store bokstaver.
  const SCRIPT_FONTS = ['script', 'dancing'];
  const caseFor = (text, font) => (SCRIPT_FONTS.includes(font) ? text : text.toUpperCase());
  async function layout(r) {
    const F = SIGN.fields;
    const one = async (text, font, field, extra = {}) => (text ? TE.layout({ lines: [text], fonts: [font], field, margin: 0.3, ...extra }) : null);
    const top1 = await one((r.top1 && r.top1.text || '').trim(), (r.top1 && r.top1.font) || 'dancing', F.top1);
    const top2Font = r.top2Font || 'serif';
    const top2 = await one(caseFor((r.top2 || '').trim(), top2Font), top2Font, F.top2, { capFit: true });
    // Stor prikk (•) gjøres om til midtprikk (·), som i originaldesignet
    const nl = (r.names || []).map((n) => (n || '').trim().replace(/•/g, '·').toUpperCase());
    const names = nl.some(Boolean) ? await TE.layout({ lines: nl, fonts: ['serif', 'serif'], ratio: 1, gap: 0.184, field: F.names, margin: 0.3, capFit: true, maxEm: 11.3 }) : null;   // maks ca. 8 mm store bokstaver, også med én linje
    return { top1, top2, names, motif: r.motif || 'fjell' };
  }

  // Alle graverte former i skiltets koordinater (mm): [{d, label}]
  function shapes(lay) {
    const F = SIGN.fields, out = [];
    const place = (res, fld, label) => {
      if (!res || !res.paths.length) return;
      const x0 = fld.cx - fld.w / 2, y0 = fld.cy - fld.h / 2;
      out.push({ label, d: TE.pathData(res.paths, 4), x: x0, y: y0 });
    };
    place(lay.top1, F.top1, 'topptekst');
    place(lay.top2, F.top2, 'undertekst');
    const md = motifD(lay.motif), M = MOTIFS[lay.motif] || {};
    // Tegnede motiver er laget i en boks på 104 × 20 mm og sentreres i motivfeltet
    if (md) out.push(M.abs ? { label: 'motiv', d: md, x: 0, y: 0, rule: M.rule }
      : { label: 'motiv', d: md, x: F.motif.cx - 52, y: F.motif.cy - 10 });
    place(lay.names, F.names, 'navn');
    return out;
  }

  // ---------- Forhåndsvisning ----------
  function roundRect(ctx, x, y, w, h, r) { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + h, r); ctx.arcTo(x + w, y + h, x, y + h, r); ctx.arcTo(x, y + h, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); }

  function render(canvas, lay, { ppm = 5, pad = 10 } = {}) {
    const W = Math.round((SIGN.w + pad * 2) * ppm), H = Math.round((SIGN.h + pad * 2) * ppm);
    canvas.width = W; canvas.height = H;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ebe9e5'; ctx.fillRect(0, 0, W, H);
    ctx.save(); ctx.translate(pad * ppm, pad * ppm); ctx.scale(ppm, ppm);
    // plate med skygge
    ctx.save(); ctx.shadowColor = 'rgba(0,0,0,.35)'; ctx.shadowBlur = 3 * ppm; ctx.shadowOffsetX = 0.8 * ppm; ctx.shadowOffsetY = 1.4 * ppm;
    roundRect(ctx, 0, 0, SIGN.w, SIGN.h, SIGN.r); ctx.fillStyle = '#111'; ctx.fill(); ctx.restore();
    const gl = ctx.createLinearGradient(0, 0, SIGN.w, SIGN.h);
    gl.addColorStop(0, 'rgba(255,255,255,.07)'); gl.addColorStop(0.5, 'rgba(255,255,255,0)'); gl.addColorStop(1, 'rgba(255,255,255,.03)');
    roundRect(ctx, 0, 0, SIGN.w, SIGN.h, SIGN.r); ctx.fillStyle = gl; ctx.fill();
    // gravering: hvit/sølvgrå, svakt matt
    ctx.fillStyle = '#e9e9e6';
    for (const s of shapes(lay)) { ctx.save(); ctx.translate(s.x, s.y); ctx.fill(new Path2D(s.d), s.rule || 'nonzero'); ctx.restore(); }
    // stålholdere
    for (const [x, y] of SIGN.holes) {
      ctx.save(); ctx.shadowColor = 'rgba(0,0,0,.45)'; ctx.shadowBlur = 1.2 * ppm; ctx.shadowOffsetX = 0.4 * ppm; ctx.shadowOffsetY = 0.6 * ppm;
      const g = ctx.createRadialGradient(x - 1.8, y - 1.8, 0.5, x, y, SIGN.capR);
      g.addColorStop(0, '#f4f4f4'); g.addColorStop(0.55, '#b9bbbd'); g.addColorStop(1, '#7c7f82');
      ctx.beginPath(); ctx.arc(x, y, SIGN.capR / 2, 0, Math.PI * 2); ctx.fillStyle = g; ctx.fill(); ctx.restore();
      ctx.beginPath(); ctx.arc(x, y, SIGN.capR / 2 - 0.4, 0, Math.PI * 2); ctx.strokeStyle = 'rgba(255,255,255,.35)'; ctx.lineWidth = 0.2; ctx.stroke();
    }
    ctx.restore();
  }

  // ---------- SVG til LightBurn: hele skiltet i mm ----------
  function toSVG(lay, { outline = true } = {}) {
    const { w, h, r } = SIGN;
    const parts = shapes(lay).map((s) => `  <path id="${s.label}" transform="translate(${f(s.x)} ${f(s.y)})" d="${s.d}" fill="#000000"${s.rule === 'evenodd' ? ' fill-rule="evenodd"' : ''}/>`).join('\n');
    const ref = outline ? `  <g id="plate" fill="none" stroke="#ff0000" stroke-width="0.1">
    <rect x="0" y="0" width="${w}" height="${h}" rx="${r}" ry="${r}"/>
${SIGN.holes.map(([x, y]) => `    <circle cx="${x}" cy="${y}" r="${SIGN.holeR}"/>`).join('\n')}
  </g>\n` : '';
    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${w}mm" height="${h}mm" viewBox="0 0 ${w} ${h}">
  <title>Dørskilt ${w} × ${h} mm</title>
${ref}${parts}
</svg>
`;
  }

  async function toPNG(lay, dpi = 600) {
    const ppm = dpi / 25.4, c = document.createElement('canvas');
    c.width = Math.round(SIGN.w * ppm); c.height = Math.round(SIGN.h * ppm);
    const ctx = c.getContext('2d'); ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, c.width, c.height); ctx.scale(ppm, ppm); ctx.fillStyle = '#000';
    for (const s of shapes(lay)) { ctx.save(); ctx.translate(s.x, s.y); ctx.fill(new Path2D(s.d), s.rule || 'nonzero'); ctx.restore(); }
    const blob = await new Promise((res) => c.toBlob(res, 'image/png'));
    return window.Engrave && Engrave.pngWithDpi ? Engrave.pngWithDpi(blob, dpi) : blob;
  }

  // Lite ikon av et motiv (SVG-markup) til valgknappene
  function motifIcon(key) {
    const d = motifD(key), F = SIGN.fields.motif, M = MOTIFS[key] || {};
    if (!d) return '';
    const vb = M.abs ? `${F.cx - 52} ${F.cy - F.h / 2} 104 ${F.h}` : `0 0 104 20`;
    return `<svg viewBox="${vb}" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="${d}" fill="currentColor" fill-rule="${M.rule || 'nonzero'}"/></svg>`;
  }

  window.DoorSign = { caseFor, SIGN, MOTIFS, layout, render, toSVG, toPNG, motifIcon };
})();

/* ---- shop/svg-eksport.js ---- */
// SVG-eksport for tekstbestillinger: en skjult side i nettbutikken som leser
// oppskriften fra lenken (#…) på ordren, viser graveringen og laster ned SVG/PNG.
// Monteres på [data-svg-eksport]. Bruker skrifter og bilde som er bakt inn i skriptet.
(function () {
  'use strict';
  const TE = window.TextEngrave;

  // Oppskrift <-> lenke (base64url av UTF-8-JSON)
  function encode(r) {
    const bytes = new TextEncoder().encode(JSON.stringify(r));
    let bin = ''; bytes.forEach((b) => { bin += String.fromCharCode(b); });
    return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  }
  function decode(s) {
    const b = atob(s.replace(/-/g, '+').replace(/_/g, '/'));
    return JSON.parse(new TextDecoder().decode(Uint8Array.from(b, (c) => c.charCodeAt(0))));
  }
  window.TekstOppskrift = { encode, decode };

  const h = (tag, attrs = {}, ...kids) => {
    const el = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k === 'class') el.className = v; else if (k.startsWith('on')) el.addEventListener(k.slice(2), v); else el.setAttribute(k, v);
    }
    for (const kid of kids.flat()) if (kid != null) el.append(kid);
    return el;
  };

  function fileName(r, ext) {
    const base = (r.lines || []).join(' ').replace(/[♥❤]/g, 'og').replace(/[æÆ]/g, 'ae').replace(/[øØ]/g, 'o').replace(/[åÅ]/g, 'a').replace(/[^\w ]+/g, '').trim().replace(/\s+/g, '-').slice(0, 40) || 'gravering';
    return `${r.product || 'gravering'}_${base}.${ext}`;
  }
  function download(blob, name) {
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
  }

  async function mount(root) {
    root.classList.add('flis-editor', 'svg-eksport');
    const mock = h('canvas', { class: 'te-canvas' });
    const tech = h('canvas', { class: 'te-canvas', style: 'background:#fff;border:1px solid #ddd;border-radius:6px' });
    const info = h('p', { class: 'fe-hint' });
    const msg = h('p', { class: 'fe-msg' });
    const svgBtn = h('button', { type: 'button', class: 'fe-add' }, 'Last ned SVG (vektor, mm)');
    const pngBtn = h('button', { type: 'button', class: 'fe-btn', style: 'margin-top:8px;width:100%;padding:12px' }, 'Last ned PNG (600 DPI)');
    const paste = h('textarea', { rows: 3, placeholder: 'Eller lim inn «_Oppskrift» fra ordren her', style: 'width:100%;margin-top:12px;font:13px monospace;padding:8px;border:1px solid #ccc;border-radius:6px' });
    root.innerHTML = '';
    root.append(h('div', { class: 'te-preview' }, mock), h('div', { style: 'margin-top:12px' }, tech), info, svgBtn, pngBtn, msg, paste);

    const img = new Image();
    const imgReady = new Promise((ok) => { img.onload = ok; img.onerror = ok; });
    let r = null, res = null;

    let tree = null;   // familietre-oppsett
    let door = null;   // dørskilt-oppsett
    async function show(recipe) {
      r = recipe;
      if (r.type === 'dorskilt' && window.DoorSign) {
        door = await DoorSign.layout(r); tree = null; res = null;
        mock.hidden = false; DoorSign.render(mock, door, { ppm: 5 });
        tech.hidden = true;
        info.textContent = `Dørskilt ${DoorSign.SIGN.w} × ${DoorSign.SIGN.h} mm, motiv: ${(DoorSign.MOTIFS[r.motif] || {}).label || ''}. ` +
          'SVG-filen er hele skiltet i riktig størrelse. Røde hårstreker viser plate og hull.';
        msg.textContent = '';
        return;
      }
      door = null; tech.hidden = false;
      if (r.type === 'familietre' && window.FamilyTree) {
        tree = await FamilyTree.layout(r); res = null;
        mock.hidden = true;
        FamilyTree.drawSheet(tech, tree, 4);
        info.textContent = `Familietre (${(FamilyTree.PRODUCT.variants[r.finish] || {}).label || ''}): «${r.bottom.text}» og ${tree.names.length} navnehjerter. ` +
          'SVG-arket har bunnteksten øverst og navnene i hjerter under. Røde hårstreker viser felt og hjerteomriss.';
        msg.textContent = '';
        return;
      }
      tree = null; mock.hidden = false;
      const product = TE.PRODUCTS[r.product] || TE.PRODUCTS.korketrekker;
      if (!img.src) img.src = TE.imageSrc(product, '');
      res = await TE.layout({ lines: r.lines, fonts: r.fonts, ratio: r.ratio, gap: r.gap, align: r.align, field: r.field || product.field });
      await imgReady;
      if (img.naturalWidth) TE.renderMock(mock, img, product, res, { zoom: 'tight', scale: 3 });
      const ppm = 14, pad = 8;
      tech.width = res.field.w * ppm + pad * 2; tech.height = res.field.h * ppm + pad * 2;
      const ctx = tech.getContext('2d');
      ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, tech.width, tech.height);
      ctx.save(); ctx.translate(pad, pad); TE.draw(ctx, res, ppm, '#000');
      ctx.setLineDash([5, 4]); ctx.strokeStyle = '#d33'; ctx.strokeRect(0, 0, res.field.w * ppm, res.field.h * ppm); ctx.restore();
      info.textContent = `«${(r.lines || []).filter(Boolean).join(' / ')}» · ${res.sizes.map((s) => `linje ${s.line}: ${s.widthMm.toFixed(1)} × ${s.heightMm.toFixed(1)} mm`).join(', ')} · felt ${res.field.w} × ${res.field.h} mm`;
      msg.textContent = '';
    }

    svgBtn.onclick = () => {
      if (door) download(new Blob([DoorSign.toSVG(door)], { type: 'image/svg+xml' }), fileName({ product: 'dorskilt', lines: r.names }, 'svg'));
      else if (tree) download(new Blob([FamilyTree.toSVG(tree)], { type: 'image/svg+xml' }), fileName({ product: 'familietre', lines: [r.bottom.text] }, 'svg'));
      else if (res) download(new Blob([TE.toSVG(res)], { type: 'image/svg+xml' }), fileName(r, 'svg'));
    };
    pngBtn.onclick = async () => {
      if (door) download(await DoorSign.toPNG(door, 600), fileName({ product: 'dorskilt', lines: r.names }, 'png'));
      else if (tree) download(await FamilyTree.toPNG(tree, 600), fileName({ product: 'familietre', lines: [r.bottom.text] }, 'png'));
      else if (res) download(await TE.toPNG(res, 600), fileName(r, 'png'));
    };
    paste.addEventListener('input', () => {
      const raw = paste.value.trim(); if (!raw) return;
      try { show(JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1))); } catch (e) { msg.textContent = 'Klarte ikke å lese oppskriften.'; }
    });

    const hash = location.hash.slice(1);
    if (hash) {
      try { await show(decode(hash)); } catch (e) { console.error(e); msg.textContent = 'Lenken inneholder ingen gyldig gravering. Lim inn «_Oppskrift» fra ordren under.'; }
    } else {
      info.textContent = 'Åpne denne siden fra lenken «_SVG-fil» på ordren, eller lim inn «_Oppskrift» under.';
    }
  }

  function mountAll() { document.querySelectorAll('[data-svg-eksport]:not(.svg-eksport)').forEach((el) => mount(el)); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mountAll); else mountAll();
  document.addEventListener('shopify:section:load', mountAll);
})();

/* ---- shop/dorskilt-editor.js ---- */
// Kunde-editor for dørskilt i akryl: topptekst (+ valgfri linje 2), motiv i midten
// og navn i bunnen (to linjer). Monteres på [data-dorskilt-editor].
(function () {
  'use strict';
  const TE = window.TextEngrave, DS = window.DoorSign;
  const EXAMPLE = { top1: 'Velkommen', top2: 'til vårt hjem', names: ['Ola · Kari', 'Emma · Jonas'] };

  const h = (tag, attrs = {}, ...kids) => {
    const el = document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (k === 'class') el.className = v; else if (k.startsWith('on')) el.addEventListener(k.slice(2), v);
      else if (k === 'html') el.innerHTML = v; else if (v !== false && v != null) el.setAttribute(k, v === true ? '' : v);
    }
    for (const kid of kids.flat()) if (kid != null) el.append(kid);
    return el;
  };
  const toBlob = (c, t, q) => new Promise((r) => c.toBlob(r, t, q));
  const insertAt = (input, txt) => {
    const pos = input.selectionStart ?? input.value.length;
    input.value = (input.value.slice(0, pos) + txt + input.value.slice(input.selectionEnd ?? pos)).replace(/\s{2,}/g, ' ').trimStart();
    input.focus();
  };

  class DorskiltEditor {
    constructor(root) {
      this.root = root;
      this.variants = JSON.parse(root.dataset.variants || '[]');
      this.variantId = (this.variants.find((v) => v.available) || this.variants[0] || {}).id;
      this.cartUrl = root.dataset.cartUrl || '/cart';
      this.exportUrl = root.dataset.exportUrl || '';
      this.font = 'dancing';
      this.font2 = 'serif';
      this.motif = 'fjell';
      this.build();
      this.loadFontFaces();
      this.schedule();
    }

    loadFontFaces() {
      if (!window.FontFace) return;
      for (const k of Object.keys(TE.FONTS)) TE.fontBuffer(k).then((b) => new FontFace('te-' + k, b).load()).then((f) => document.fonts.add(f)).catch(() => {});
    }

    build() {
      const r = this.root;
      r.classList.add('flis-editor', 'tekst-editor', 'dorskilt-editor');
      r.innerHTML = '';
      this.canvas = h('canvas', { class: 'te-canvas', 'aria-label': 'Forhåndsvisning av dørskiltet' });
      this.badge = h('span', { class: 'te-badge' }, 'Eksempel');
      const input = (ph, max) => h('input', { type: 'text', maxlength: max, placeholder: ph, oninput: () => this.schedule() });
      this.top1 = input('f.eks. Velkommen', 24);
      this.top2 = input('f.eks. til vårt hjem (valgfri)', 30);
      this.name1 = input('f.eks. Ola · Kari', 32);
      this.name2 = input('f.eks. Emma · Jonas (valgfri)', 32);
      const fontChips = (key) => Object.entries(TE.FONTS).map(([k, f]) => h('button', { type: 'button', class: 'fe-chip te-font', 'data-v': k,
        style: `font-family:'te-${k}',serif`, onclick: () => { this[key] = k; this.sync(); this.schedule(); } }, f.label));
      this.fontChips = fontChips('font');
      this.fontChips2 = fontChips('font2');
      this.motifChips = Object.entries(DS.MOTIFS).filter(([, m]) => !m.hidden).map(([k, m]) => h('button', { type: 'button', class: 'fe-chip ds-motif', 'data-v': k, title: m.label,
        onclick: () => { this.motif = k; this.sync(); this.schedule(); } }, h('span', { class: 'ds-icon', html: DS.motifIcon(k) || '–' }), h('span', {}, m.label)));
      const dotBtn = (inp) => h('button', { type: 'button', class: 'fe-btn te-heart', title: 'Sett inn prikk mellom navn', onclick: () => { insertAt(inp, ' · '); this.schedule(); } }, '·');
      this.info = h('p', { class: 'fe-hint' });
      this.addBtn = h('button', { type: 'button', class: 'fe-add', onclick: () => this.addToCart() });
      this.msg = h('p', { class: 'fe-msg', role: 'status' });

      let variantEl = null;
      if (this.variants.length > 1) {
        variantEl = h('label', { class: 'fe-field' }, 'Variant', h('select', { onchange: (e) => { this.variantId = +e.target.value; this.updateButton(); } },
          this.variants.map((v) => h('option', { value: v.id, disabled: !v.available, selected: v.id === this.variantId }, `${v.title} – ${v.price}`))));
      }

      r.append(...[
        h('div', { class: 'te-preview' }, this.canvas, this.badge),
        h('div', { class: 'fe-section' }, h('h3', {}, 'Tekst øverst'),
          h('label', { class: 'fe-field' }, 'Topptekst', this.top1),
          h('div', { class: 'fe-row te-fonts' }, this.fontChips),
          h('label', { class: 'fe-field' }, 'Linje 2 (valgfri)', this.top2),
          h('div', { class: 'fe-row te-fonts' }, this.fontChips2)),
        h('div', { class: 'fe-section' }, h('h3', {}, 'Motiv'), h('div', { class: 'fe-row ds-motifs' }, this.motifChips)),
        h('div', { class: 'fe-section' }, h('h3', {}, 'Navn'),
          h('label', { class: 'fe-field' }, 'Linje 1', h('div', { class: 'te-inputrow' }, this.name1, dotBtn(this.name1))),
          h('label', { class: 'fe-field' }, 'Linje 2 (valgfri)', h('div', { class: 'te-inputrow' }, this.name2, dotBtn(this.name2))),
          h('p', { class: 'fe-hint' }, 'Navnene graveres med store bokstaver, og linje 2 også med Klassisk, Romersk eller Moderne. Bruk · for å skille navn.')),
        variantEl, this.info,
        h('p', { class: 'fe-note' }, `Sort akryl med hvit gravering, ${DS.SIGN.w} × ${DS.SIGN.h} mm. Vi sjekker hver tekst før gravering.`),
        this.addBtn, this.msg,
      ].filter(Boolean));
      this.sync();
    }

    sync() {
      for (const c of this.fontChips) c.classList.toggle('active', c.dataset.v === this.font);
      for (const c of this.fontChips2) c.classList.toggle('active', c.dataset.v === this.font2);
      for (const c of this.motifChips) c.classList.toggle('active', c.dataset.v === this.motif);
      this.updateButton();
    }

    isEmpty() { return ![this.top1, this.top2, this.name1, this.name2].some((x) => x.value.trim()); }

    recipe(example) {
      return { v: 1, type: 'dorskilt', product: 'dorskilt', motif: this.motif,
        top1: { text: example ? EXAMPLE.top1 : this.top1.value.trim(), font: this.font },
        top2: example ? EXAMPLE.top2 : this.top2.value.trim(), top2Font: this.font2,
        names: example ? EXAMPLE.names : [this.name1.value.trim(), this.name2.value.trim()] };
    }

    schedule() {
      if (this.pending) return;
      this.pending = true;
      requestAnimationFrame(async () => { this.pending = false; await this.render(); });
    }

    async render() {
      const example = this.isEmpty();
      try { this.lay = await DS.layout(this.recipe(example)); } catch (e) {
        console.error(e); this.msg.textContent = `Klarte ikke å laste skriftene (${e.message}). Last siden på nytt.`; return;
      }
      this.badge.hidden = !example;
      DS.render(this.canvas, this.lay, { ppm: 5 });
      const small = !example && this.lay.names && this.lay.names.sizes.some((s) => s.heightMm < 4.5);
      this.info.textContent = small ? 'Navnene blir ganske små. Kortere linjer gir større bokstaver.' : '';
      this.updateButton();
    }

    updateButton() {
      const v = this.variants.find((x) => x.id === this.variantId);
      if (v && !v.available) { this.addBtn.textContent = 'Utsolgt'; this.addBtn.disabled = true; return; }
      this.addBtn.disabled = false;
      this.addBtn.textContent = this.isEmpty() ? 'Skriv teksten først' : `Legg i handlekurven${v ? ' – ' + v.price : ''}`;
    }

    async addToCart() {
      if (this.isEmpty()) { this.top1.focus(); return; }
      if (!this.variantId) { this.msg.textContent = 'Produktet mangler variant. Kontakt butikken.'; return; }
      this.addBtn.disabled = true; this.addBtn.textContent = 'Legger i handlekurven …'; this.msg.textContent = '';
      try {
        const r = this.recipe(false);
        const lay = await DS.layout(r);
        const fd = new FormData();
        fd.append('id', this.variantId);
        fd.append('quantity', 1);
        if (r.top1.text) fd.append('properties[Topptekst]', r.top1.text);
        if (r.top2) fd.append('properties[Linje 2]', DS.caseFor(r.top2, r.top2Font));
        fd.append('properties[Motiv]', DS.MOTIFS[r.motif].label);
        const nm = r.names.filter(Boolean).map((n) => n.toUpperCase());
        if (nm.length) fd.append('properties[Navn]', nm.join(' / '));
        fd.append('properties[Skrift]', r.top2 ? `${TE.FONTS[r.top1.font].label} / ${TE.FONTS[r.top2Font].label}` : TE.FONTS[r.top1.font].label);
        const c = document.createElement('canvas');
        DS.render(c, lay, { ppm: 5 });
        fd.append('properties[Forhåndsvisning]', new File([await toBlob(c, 'image/jpeg', 0.9)], 'forhandsvisning.jpg', { type: 'image/jpeg' }));
        fd.append('properties[_Oppskrift]', JSON.stringify(r));
        if (this.exportUrl && window.TekstOppskrift) fd.append('properties[_SVG-fil]', this.exportUrl + '#' + window.TekstOppskrift.encode(r));
        const root = (window.Shopify && window.Shopify.routes && window.Shopify.routes.root) || '/';
        const resp = await fetch(root + 'cart/add.js', { method: 'POST', body: fd, headers: { Accept: 'application/json' } });
        if (!resp.ok) {
          let desc = ''; try { desc = (await resp.json()).description || ''; } catch (e) { /* ignorer */ }
          throw new Error(desc || `HTTP ${resp.status}`);
        }
        this.addBtn.textContent = 'Lagt i handlekurven ✔';
        window.location.href = this.cartUrl;
      } catch (e) {
        console.error(e);
        this.msg.textContent = `Noe gikk galt: ${e.message}. Prøv igjen, eller kontakt oss.`;
        this.updateButton();
      }
    }
  }

  function mountAll() {
    document.querySelectorAll('[data-dorskilt-editor]:not(.dorskilt-editor)').forEach((el) => {
      try { el._dsEditor = new DorskiltEditor(el); } catch (e) {
        console.error('Dørskilt-editor:', e);
        el.innerHTML = '<p style="color:#b00020;text-align:center">Verktøyet kunne ikke starte: ' + String(e && e.message || e).replace(/[<>&]/g, '') + '</p>';
      }
    });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', mountAll); else mountAll();
  document.addEventListener('shopify:section:load', mountAll);
})();
